import React from 'react';
import { Container, Row, Col, Card } from 'react-bootstrap';
import { FaGraduationCap, FaBook, FaUniversity, FaChartLine, FaFlask, FaNetworkWired } from 'react-icons/fa';

const Home = () => {
    const concours = [
        {
            id: 1,
            title: 'Concours Polytech',
            description: 'Préparation aux concours des écoles d\'ingénieurs Polytech',
            icon: <FaFlask />,
            details: [
                'Concours Polytech PEIP',
                'Concours Polytech 3/2',
                'Concours Polytech MP',
                'Concours Polytech PC'
            ]
        },
        {
            id: 2,
            title: 'ENPT',
            description: 'Préparation au concours de l\'École Nationale des Postes et Télécommunications',
            icon: <FaNetworkWired />,
            details: [
                'Concours Ingénieur',
                'Concours Technicien',
                'Concours Administratif',
                'Formation continue'
            ]
        },
        {
            id: 3,
            title: 'Concours Administratifs',
            description: 'Préparation aux concours de la fonction publique',
            icon: <FaGraduationCap />,
            details: [
                'Concours de catégorie A',
                'Concours de catégorie B',
                'Concours de catégorie C',
                'Concours spécialisés'
            ]
        },
        {
            id: 4,
            title: 'Concours Paramédicaux',
            description: 'Formation pour les concours du secteur médical',
            icon: <FaBook />,
            details: [
                'IFSI (Infirmier)',
                'Orthophoniste',
                'Kinésithérapeute',
                'Psychomotricien'
            ]
        }
    ];

    return (
        <div>
            {/* Hero Section */}
            <section className="hero-section text-center">
                <Container>
                    <h1>Préparation aux Concours</h1>
                    <p className="lead">
                        Une formation complète et personnalisée pour réussir vos concours
                    </p>
                </Container>
            </section>

            {/* Concours Section */}
            <section className="py-5">
                <Container>
                    <h2 className="text-center section-title">Nos Formations</h2>
                    <Row>
                        {concours.map((concour) => (
                            <Col key={concour.id} md={6} lg={3}>
                                <Card className="h-100">
                                    <Card.Body>
                                        <div className="icon-container">
                                            {concour.icon}
                                        </div>
                                        <Card.Title className="text-center">{concour.title}</Card.Title>
                                        <Card.Text className="text-center">{concour.description}</Card.Text>
                                        <ul className="list-unstyled mt-3">
                                            {concour.details.map((detail, index) => (
                                                <li key={index} className="mb-2">
                                                    <small>{detail}</small>
                                                </li>
                                            ))}
                                        </ul>
                                    </Card.Body>
                                </Card>
                            </Col>
                        ))}
                    </Row>
                </Container>
            </section>
        </div>
    );
};

export default Home;
